(1, 1, 'OEC-CG100-K1', 'oec-cg100-k1', 'OEC OEC-CG100-K1, Aluminum Cord Grip Connector, Cable Range (Min/Max) 0.438 - 0.750, Straight, 1 in NPT.', '<ul class=\"feature-list\">\n<li>Aluminum cord connector provides durable performance</li>\n<li>Lightweight design</li>\n</ul>', NULL, NULL, NULL, NULL),
(2, 2, 'TKMC050A075', 'tkmc050a075', 'OEC TKMC050A075, Cable Gland, Metal-clad, TECK Corrugated or Interlocked Steel, or Aluminum, Armoured, Outer Jacket Min 0.520 & 0.720 Max, General purpose, 1/2 in, NPT, Armoured Dia Min 0.440 & 0.610 Max', '<ul class=\"feature-list\"><li>Simplified two part design</li><li>Compact profile</li><li>Enhance reliability, reduce risk</li><li>Reduces man hours &amp; cost</li></ul>', NULL, NULL, NULL, NULL),
(3, 2, 'TKMC075A075', 'tkmc075a075', 'OEC TKMC075A075, Cable Gland, Metal-clad, TECK Corrugated or Interlocked Steel, or Aluminum, Armoured, Outer Jacket Min 0.520 & 0.720 Max, General purpose, 3/4 in, NPT, Armoured Dia Min 0.440 & 0.610 Max', '<ul class=\"feature-list\"><li>Simplified two part design</li><li>Compact profile</li><li>Enhance reliability, reduce risk</li><li>Reduces man hours &amp; cost</li></ul>', NULL, NULL, NULL, NULL),
(4, 2, 'TKMC050A099', 'tkmc050a099', 'OEC TKMC050A099, Cable Gland, Metal-clad, TECK Corrugated or Interlocked Steel, or Aluminum, Armoured, Outer Jacket Min 0.710 & 0.980 Max, General purpose, 1/2 in, NPT, Armoured Dia Min 0.620 & 0.860 Max', '<ul class=\"feature-list\"><li>Simplified two part design</li><li>Compact profile</li><li>Enhance reliability, reduce risk</li><li>Reduces man hours &amp; cost</li></ul>', NULL, NULL, NULL, NULL),
