(1356, 3, '98106R', '98106r', 'OEC 98106R, 350 Kcmil, 1/2 in Stud, 1-3/4 in Hole Spacing, Copper, Two Hole 90 Deg Long Barrel, Compression Lug, Compact Class B, C, Flex Class G, H, I, K, M & DLO, Color Coded, Cu Only', '<ul class=\"feature-list\"><li>Manufactured from high strength seamless copper tubing</li><li>Chamfered entry</li><li>Color coded die index and crimp marks</li><li>Electro-Tin plated for corrosion resistance</li><li>Inspection window to ensure full cable insertion</li><li>UL486A/B Listed for Wire Connectors</li><li>Listed for use with class B &amp; C, flex class G, H, I, K, M &amp; DLO cable</li></ul>', NULL, NULL, NULL, NULL),
(1357, 8, '23101', '23101', 'OEC 23101, Copper, Thin Wall, Compression C Tap, Run 12 AWG, Tap 14 - 12 AWG, Color Coded, Die Index, Cu Only', '<ul class=\"feature-list\">\n 	<li>Manufactured from high conductivity copper</li>\n 	<li>Range taking</li>\n 	<li>Color coded for proper crimp die selection</li>\n 	<li>Provides maximum conductivity and low contact resistance</li>\n 	<li>Direct burial in earth or concrete</li>\n 	<li>Low installation cost</li>\n 	<li>Compact size allows for easy taping and insulation of connection</li>\n 	<li>Applications include copper tapping, Splicing/pig tailing</li>\n 	<li>Allows for 2 continuous parallel conductor</li>\n</ul>', NULL, NULL, NULL, NULL),
